import { useCallback, useEffect, useRef, useState } from "react";
import { useTime } from "../../context/TimeContext";
import { useLang } from "../../context/LangContext";
import { buildSearch, readUrlState, writeSearchToUrl } from "../../utils/urlState";

// À rendre À L'INTÉRIEUR de <TimeProvider> (il lit/écrit la période).
//  - au montage : applique la période de l'URL (si présente) ;
//  - ensuite : réécrit l'URL (replaceState, débouncé) à chaque changement
//    de filtre / période / rectangle / tweet sélectionné / déplacement carte ;
//  - affiche un bouton "Copier le lien".
//
// `syncRef` : ref que MapView appelle sur "moveend" (via onMoveEnd) pour
// déclencher l'écriture sans re-rendre App.
export default function UrlStateSync({
  activeWeaponTypes,
  activeObjectiveTypes,
  activeLabel,
  searchText,
  spatialRectangle,
  selectedTweetId,
  mapRef,
  syncRef,
}) {
  const { timeRange, setRange } = useTime();
  const { lang, t } = useLang();
  const [copied, setCopied] = useState(false);

  // 1. Période initiale depuis l'URL (EventsChart saute alors sa sélection auto)
  useEffect(() => {
    const s = readUrlState();
    if (s.from && s.to) setRange(s.from, s.to);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Toujours la dernière valeur, sans recréer le callback d'écriture
  const latest = useRef({});
  latest.current = {
    timeRange,
    weapons: activeWeaponTypes,
    objectives: activeObjectiveTypes,
    label: activeLabel,
    search: searchText,
    rectangle: spatialRectangle,
    tweetId: selectedTweetId,
  };

  const timer = useRef(null);
  const writeNow = useCallback(() => {
    clearTimeout(timer.current);
    const view = mapRef.current?.getView?.() ?? readUrlState().view;
    writeSearchToUrl(buildSearch({ ...latest.current, view }));
  }, [mapRef]);

  const scheduleWrite = useCallback(() => {
    clearTimeout(timer.current);
    timer.current = setTimeout(writeNow, 400);
  }, [writeNow]);

  useEffect(() => {
    if (syncRef) syncRef.current = scheduleWrite;
    return () => {
      if (syncRef) syncRef.current = null;
      clearTimeout(timer.current);
    };
  }, [scheduleWrite, syncRef]);

  useEffect(() => {
    scheduleWrite();
  }, [
    scheduleWrite,
    timeRange.start, timeRange.end,
    activeWeaponTypes, activeObjectiveTypes, activeLabel,
    searchText, spatialRectangle, selectedTweetId,
  ]);

  const handleCopy = async () => {
    writeNow(); // l'URL doit être à jour avant de la copier
    const url = window.location.href;
    try {
      if (navigator.share && window.matchMedia("(max-width: 768px)").matches) {
        await navigator.share({ url });
        return;
      }
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch (err) {
      if (err?.name !== "AbortError") window.prompt("URL :", url);
    }
  };


}