import MapView from "./components/Map/MapView";
import LoadingGlobe from "./components/Map/LoadingGlobe";
import SidePanel from "./components/SidePanel/SidePanel";
import ContentPanel from "./components/ContentPanel/ContentPanel";
import { TimeProvider } from "./context/TimeContext";
import { LayerProvider } from "./context/LayerContext";
import { BootstrapProvider } from "./context/BootstrapContext";
import { useLang } from "./context/LangContext";
import { useState, useEffect, useRef } from "react";
import "./utils/popupUtils.css";
import "./App.css";
import "./seo-headings.css";
import EventsChart from "./components/EventsChart/EventsChart";
import MapFilters from "./components/MapFilters/MapFilters"
import UrlStateSync from "./components/UrlStateSync/UrlStateSync";
import { readUrlState } from "./utils/urlState";

// Points animés du texte "Chargement...". L'état et le setInterval vivent ICI,
// dans un mini-composant : seul ce composant se re-rend toutes les 400ms, et
// non plus toute l'application (MapView, SidePanel, EventsChart...). Comme il
// est démonté avec l'overlay, l'intervalle est nettoyé automatiquement.
function LoadingDots() {
  const [n, setN] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setN((d) => (d + 1) % 4), 400);
    return () => clearInterval(id);
  }, []);
  return <>{'.'.repeat(n)}</>;
}

// Application cartographique (carte + SidePanel + tweets + graphique).
// Chargée en lazy depuis App.jsx : n'est PAS téléchargée sur /content/<slug>/.
export default function MapApp() {
  const { t, lang, toggleLang } = useLang();
  const [tweets, setTweets] = useState(null);
  const [contentPanelOpen, setContentPanelOpen] = useState(true);
  const [openPanel, setOpenPanel] = useState(null);
  const [sidePanelCollapsed, setSidePanelCollapsed] = useState(false);
  const mapRef = useRef(null);
  // État initial lu depuis l'URL (permalinks), voir utils/urlState.js
  const [activeLabel, setActiveLabel] = useState(() => readUrlState().label);
  // MapView appelle viewSyncRef.current() sur "moveend" ; UrlStateSync y branche
  // son écriture débouncée (ref => aucun re-render d'App à chaque déplacement).
  const viewSyncRef = useRef(null);
  const [chartOpen, setChartOpen] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(() => {
    const s = readUrlState();
    return s.weapons.length > 0 || s.objectives.length > 0;
  });
  const [activeWeaponTypes, setActiveWeaponTypes] = useState(() => readUrlState().weapons);
  const [activeObjectiveTypes, setActiveObjectiveTypes] = useState(() => readUrlState().objectives);
  // searchText est débouncé (300ms) à la source, directement dans MapView
  // (l'input local n'y remonte la valeur qu'après une pause de frappe). Donc
  // ici, App reçoit déjà une valeur "stable" : pas besoin d'un second
  // debounce avant de la transmettre à EventsChart.
  const [searchText, setSearchText] = useState(() => readUrlState().search);
  // Rectangle spatial tracé sur la carte (cf. MapView "Draw area"), levé ici
  // pour pouvoir aussi filtrer le graphique EventsChart en plus de la carte.
  const [spatialRectangle, setSpatialRectangle] = useState(() => readUrlState().rectangle);
  // Écran de chargement plein page : reste affiché tant que MapView n'a pas
  // fini de charger les données (bootstrap + sources MapLibre).
  const [appLoading, setAppLoading] = useState(true);
  // Garde-fou : si la carte n'a pas fini de charger au bout de 6s (clé MapTiler
  // refusée, réseau lent, rendu Googlebot / Search Console...), on retire
  // l'overlay quand même. Sans ça, l'écran de chargement reste affiché
  // indéfiniment et les crawlers ne voient jamais le reste de l'UI.
  // Si MapView a déjà appelé onLoadingChange(false), c'est un no-op.
  useEffect(() => {
    const id = setTimeout(() => setAppLoading(false), 6000);
    return () => clearTimeout(id);
  }, []);
  // Une fois le chargement terminé, on laisse le fondu (0.4s) se jouer puis on
  // DÉMONTE l'overlay : sinon il reste par-dessus la carte (opacity 0) et
  // LoadingGlobe continue de tourner en arrière-plan pour rien.
  const [showOverlay, setShowOverlay] = useState(true);
  useEffect(() => {
    if (appLoading) return;
    const id = setTimeout(() => setShowOverlay(false), 500);
    return () => clearTimeout(id);
  }, [appLoading]);

  // Id du tweet actuellement sélectionné depuis le SidePanel (clic sur une
  // carte). Sert à la fois à surligner la carte dans le SidePanel et à
  // afficher l'indicateur correspondant sur la carte.
  const [selectedTweetId, setSelectedTweetId] = useState(() => readUrlState().tweetId);

  const handleTweetClick = (feature) => {
    const id = feature.properties.id;

    // Re-clic sur le tweet déjà sélectionné => on le désélectionne.
    // String() car l'id lu depuis l'URL (permalink) est une chaîne, alors que
    // feature.properties.id peut être un nombre.
    if (selectedTweetId != null && String(id) === String(selectedTweetId)) {
      setSelectedTweetId(null);              // UrlStateSync retire alors "tweet=" de l'URL
      mapRef.current?.clearTweetHighlight?.(); // ferme la popup mobile + retire le cercle
      return;
    }

    setSelectedTweetId(id);
    mapRef.current?.highlightTweet(feature);
  };
  const [availableWeaponTypes, setAvailableWeaponTypes] = useState([]);
  const [availableObjectiveTypes, setAvailableObjectiveTypes] = useState([]);
  const togglePanel = (panel) => setOpenPanel((current) => (current === panel ? null : panel));

  // Overlay plein page affiché tant que appLoading est true. En "fixed" avec
  // un zIndex élevé, il masque tout le reste de l'UI (carte, panneaux,
  // barres) quel que soit le layout (mobile ou desktop) en dessous.
  const loadingOverlay = (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 16,
        background: 'var(--ox-bg, #0d1320)',
        opacity: appLoading ? 1 : 0,
        pointerEvents: appLoading ? 'auto' : 'none',
        transition: 'opacity 0.4s ease',
      }}
    >
      <LoadingGlobe size="clamp(200px, 40vmin, 480px)" />
      <span style={{ color: '#e1e1e1', fontSize: 14, letterSpacing: 0.3, minWidth: '110px', textAlign: 'center' }}>
        {t.loading}<LoadingDots />
      </span>
    </div>
  );



  useEffect(() => {
    if (!tweets) return;
    // Priorité à la liste calculée par MapView pour la période courante
    // (indépendante du filtre armes actif, donc elle ne se réduit pas
    // quand on coche un filtre).
    if (tweets.availableWeaponTypesForTimeRange) {
      setAvailableWeaponTypes(tweets.availableWeaponTypesForTimeRange);
      return;
    }
    // Fallback (ex: tout premier chargement, avant que MapView n'ait
    // injecté les métadonnées de période).
    if (tweets.features) {
      const uniqueTypes = [...new Set(
        tweets.features
          .map(f => f.properties?.weapon_type)
          .filter(Boolean)
      )].sort();
      setAvailableWeaponTypes(uniqueTypes);
    }
  }, [tweets]);

  useEffect(() => {
    if (!tweets) return;
    // Priorité à la liste calculée par MapView pour la période courante
    // (indépendante du filtre objectifs actif, donc elle ne se réduit pas
    // quand on coche un filtre).
    if (tweets.availableObjectiveTypesForTimeRange) {
      setAvailableObjectiveTypes(tweets.availableObjectiveTypesForTimeRange);
      return;
    }
    // Fallback (ex: tout premier chargement, avant que MapView n'ait
    // injecté les métadonnées de période).
    if (tweets.features) {
      const uniqueTypes = [...new Set(
        tweets.features
          .map(f => f.properties?.objective_type)
          .filter(Boolean)
      )].sort();
      setAvailableObjectiveTypes(uniqueTypes);
    }
  }, [tweets]);
  return (
    <BootstrapProvider>
      <TimeProvider>
        <LayerProvider>
          {showOverlay && loadingOverlay}
          {/* Titre principal de la page (masqué visuellement, lu par Google et les lecteurs d'écran) */}
          <h1 className="visually-hidden">{t.pageTitle}</h1>
          <div className="app-shell">

            {/* 1. SidePanel — le bouton toggle est à l'intérieur quand il est ouvert */}
            <SidePanel
              tweets={tweets}
              collapsed={sidePanelCollapsed}
              activeLabel={activeLabel}
              onLabelChange={setActiveLabel}
              onTweetClick={handleTweetClick}
              selectedTweetId={selectedTweetId}
              onToggle={() => setSidePanelCollapsed(true)}
              onResize={() => mapRef.current?.resize?.()}
            />

            {/* 2. Zone de droite */}
            <div style={{
              flex: 1,
              minWidth: 0,
              position: 'relative',
              // Crée un contexte d'empilement (< z-index du SidePanel = 100) :
              // tout ce qui est dans la zone carte (popups bottom sheet à
              // z-index 1000, boutons, tiroirs...) reste DERRIÈRE le SidePanel.
              zIndex: 0,
              display: 'flex',
              flexDirection: 'column'
            }}>

              {/* Bouton rouvrir — visible UNIQUEMENT quand le panel est fermé */}
              {sidePanelCollapsed && openPanel !== "topics" && (
                <button
                  type="button"
                  className="map-ctrl-btn map-ctrl-btn--float sidepanel-reopen"
                  onClick={() => setSidePanelCollapsed(false)}
                  aria-label={t.expandPanel ?? "Expand panel"}
                  style={{ left: 8 }}
                >
                  {/* Icône ←| (miroir de |→) pour indiquer "ouvrir vers la droite" */}
                  <svg
                    width="16" height="16" viewBox="0 0 16 16"
                    fill="none" xmlns="http://www.w3.org/2000/svg"
                    aria-hidden="true"
                  >
                    <line x1="12" y1="2" x2="12" y2="14" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
                    <path d="M9 8 L3 8 M6 5 L3 8 L6 11" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                </button>
              )}
              
              {/* 
            <TopBar
              togglePanel={togglePanel}
              openPanel={openPanel}
              sidePanelCollapsed={sidePanelCollapsed}
            /> */}
              <div style={{ flex: 1, position: 'relative' }}>
                {filtersOpen && (
                  <MapFilters
                    activeWeaponTypes={activeWeaponTypes}
                    setActiveWeaponTypes={setActiveWeaponTypes}
                    availableWeaponTypes={availableWeaponTypes}
                    activeObjectiveTypes={activeObjectiveTypes}
                    setActiveObjectiveTypes={setActiveObjectiveTypes}
                    availableObjectiveTypes={availableObjectiveTypes}
                    onClose={() => setFiltersOpen(false)}
                  />
                )}
                <MapView
                  ref={mapRef}
                  onTweetsLoaded={setTweets}
                  activeLabel={activeLabel}
                  activeWeaponTypes={activeWeaponTypes}
                  activeObjectiveTypes={activeObjectiveTypes}
                  searchText={searchText}
                  onSearchTextChange={setSearchText}
                  searchBarLeftOffset={sidePanelCollapsed && openPanel !== "topics" ? 50 : 8}
                  filtersOpen={filtersOpen}
                  onToggleFilters={() => setFiltersOpen(v => !v)}
                  onRectangleDrawn={setSpatialRectangle}
                  onLoadingChange={setAppLoading}
                  onTweetPopupClose={() => setSelectedTweetId(null)}
                  selectedTweetId={selectedTweetId}
                  sidePanelOpen={!sidePanelCollapsed}
                  initialView={readUrlState().view}
                  initialRectangle={readUrlState().rectangle}
                  initialTweetId={readUrlState().tweetId}
                  onMoveEnd={() => viewSyncRef.current?.()}
                />
                <UrlStateSync
                  activeWeaponTypes={activeWeaponTypes}
                  activeObjectiveTypes={activeObjectiveTypes}
                  activeLabel={activeLabel}
                  searchText={searchText}
                  spatialRectangle={spatialRectangle}
                  selectedTweetId={selectedTweetId}
                  mapRef={mapRef}
                  syncRef={viewSyncRef}
                />
              </div>
              <ContentPanel isOpen={contentPanelOpen} onToggle={() => setContentPanelOpen(v => !v)} />
              <EventsChart
                activeWeaponTypes={activeWeaponTypes}
                activeObjectiveTypes={activeObjectiveTypes}
                activeLabel={activeLabel}
                searchText={searchText}
                spatialRectangle={spatialRectangle}
                isOpen={chartOpen}
                onToggle={() => {
                  setChartOpen(v => !v);
                  setTimeout(() => mapRef.current?.resize?.(), 250);
                }}
              />
              {/* <StatusBar /> */}
            </div>

          </div>
        </LayerProvider>
      </TimeProvider>
    </BootstrapProvider>
  );
}