// Routage "une URL par théâtre" : /content/<slug>/
//
// Le HTML de ces pages est généré au build (scripts/inject-seo.js) ; ici on
// gère le côté client : lire le slug au démarrage, et tenir l'URL à jour quand
// l'utilisateur ouvre / ferme un théâtre dans le panneau.
//
// UrlStateSync réécrit uniquement la partie "?query" (writeSearchToUrl garde
// window.location.pathname), donc le chemin posé ici n'est jamais écrasé.

const PATH_RE = /^\/content\/([a-z0-9-]+)\/?$/;

let initialSlug; // undefined = pas encore lu ; mémoïsé comme readUrlState()

// Slug présent dans l'URL au chargement de la page (null si on est sur "/").
export function getInitialTheaterSlug() {
  if (initialSlug === undefined) {
    const m = window.location.pathname.match(PATH_RE);
    initialSlug = m ? m[1] : null;
  }
  return initialSlug;
}

// Même règle que _slugify() dans main.py (utilisé seulement si le bootstrap
// ne fournit pas encore le champ SLUG).
export const slugify = (label) =>
  String(label || "")
    .normalize("NFKD")
    .replace(/[^\x00-\x7F]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

export const theaterSlug = (topic) => topic?.SLUG || slugify(topic?.LABEL);

// Met le chemin à /content/<slug>/ (ou "/" si slug = null), en gardant ?query et #hash.
export function setTheaterPath(slug) {
  const target = slug ? `/content/${slug}/` : "/";
  if (window.location.pathname === target) return;
  window.history.replaceState(
    null,
    "",
    `${target}${window.location.search}${window.location.hash}`
  );
}

// Même titre que les pages statiques (anglais) ; en français : "<théâtre> | OSINT Watch".
export const theaterTitle = (rawLabel, localizedLabel, lang) =>
  lang === "en" || !localizedLabel
    ? `${rawLabel}: latest OSINT updates and map | OSINT Watch`
    : `${localizedLabel} | OSINT Watch`;